#include <bits/stdc++.h>
using namespace std;

const int MAXN = (1 << 19) | 5;
int n, k, p, maxn, count_arr[MAXN], f_arr[MAXN];
int tmp1_arr[20][MAXN], tmp2_arr[20][MAXN], tmp3_arr[20][MAXN];
long long total_power;
long long transform_arr[20][MAXN];
long long fact[MAXN], inv_fact[MAXN];

long long bin_pow(long long base, long long exp) {
    long long res = 1, cur = base;
    while (exp > 0) {
        if (exp & 1) res = res * cur % p;
        cur = cur * cur % p;
        exp >>= 1;
    }
    return res;
}

void prepare() {
    fact[0] = 1;
    for (int i = 1; i <= maxn; i++)
        fact[i] = fact[i - 1] * i % p;
    inv_fact[maxn] = bin_pow(fact[maxn], p - 2);
    for (int i = maxn - 1; i >= 0; i--)
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % p;
}

int get_lower(int x) {
    int res = 1;
    while (res < x) res <<= 1;
    return res;
}

void transform_FWT(int *arr, int len, bool inv = false) {
    long long *temp = transform_arr[0];
    for (int i = 0; i < len; i++) temp[i] = arr[i];
    for (int step = 1; step < len; step <<= 1) {
        for (int j = 0; j < len; j += (step << 1)) {
            for (int k = j; k < j + step; k++) {
                long long val = temp[k];
                if (inv) {
                    temp[k + step] -= val;
                } else {
                    temp[k + step] += val;
                }
            }
        }
    }
    for (int i = 0; i < len; i++) {
        arr[i] = (int)(temp[i] % p);
        if (arr[i] < 0) arr[i] += p;
    }
}

inline void mod_adjust(long long &x) { if (x >= total_power) x -= total_power; }

void multiply() {
    memset(tmp1_arr, 0, sizeof tmp1_arr);
    memset(transform_arr, 0, sizeof transform_arr);
    for (int i = 0; i <= maxn; i++)
        tmp1_arr[count_arr[i]][i] = f_arr[i];
    for (int j = 0; j <= 19; j++)
        transform_FWT(tmp1_arr[j], maxn + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; l + q <= 19; l++)
            for (int s = 0; s <= maxn; s++)
                mod_adjust(transform_arr[q + l][s] += 1LL * tmp1_arr[q][s] * tmp2_arr[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= maxn; s++)
            tmp3_arr[q][s] = (int)(transform_arr[q][s] % p);
    for (int j = 0; j <= 19; j++)
        transform_FWT(tmp3_arr[j], maxn + 1, true);
    for (int j = 0; j <= maxn; j++)
        f_arr[j] = tmp3_arr[count_arr[j]][j];
}

void multiply_alt() {
    static int temp[20][MAXN];
    for (int i = 0; i <= 19; i++)
        memset(transform_arr[i], 0, sizeof(long long) * (maxn + 1));
    for (int q = 0; q <= 19; q++)
        for (int l = 0; l + q <= 19; l++)
            for (int s = 0; s <= maxn; s++)
                mod_adjust(transform_arr[q + l][s] += 1LL * tmp2_arr[q][s] * tmp2_arr[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= maxn; s++)
            temp[q][s] = (int)(transform_arr[q][s] % p);
    for (int i = 0; i <= 19; i++)
        transform_FWT(temp[i], maxn + 1, true);
    for (int i = 0; i <= 19; i++)
        memset(tmp2_arr[i], 0, sizeof(int) * (maxn + 1));
    for (int i = 0; i <= maxn; i++)
        tmp2_arr[count_arr[i]][i] = temp[count_arr[i]][i];
    for (int i = 0; i <= 19; i++)
        transform_FWT(tmp2_arr[i], maxn + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    total_power = 1LL * p * p;
    if (n & 1) {
        printf("%lld", bin_pow(k, n));
        return 0;
    }
    f_array[0] = 1;
    maxn = get_lower(n + 1) - 1;
    prepare();
    for (int i = 0; i <= maxn; i++)
        count_arr[i] = __builtin_popcount(i);
    for (int i = 0; i <= maxn; i++)
        tmp2_arr[count_arr[i]][i] = inv_fact[i];
    for (int i = 0; i <= 19; i++)
        transform_FWT(tmp2_arr[i], maxn + 1);
    int res_k = k;
    while (res_k) {
        if (res_k & 1) multiply();
        res_k >>= 1;
        if (res_k) multiply_alt();
    }
    printf("%lld", (bin_pow(k, n) - fact[n] * f_array[n] % p + p) % p);
    return 0;
}
